import { FileUpload } from '@absoluteui/components/file-upload';

const host = document.querySelector<HTMLElement>('#attachments');
if (host) {
  const upload = FileUpload.create(host, {
    label: 'Attachments',
    name: 'attachments',
    multiple: true,
    acceptTypes: ['application/pdf', 'image/*'],
    acceptExtensions: ['.pdf', '.png', '.jpg'],
    maxFileSize: 5_000_000,
    maxFiles: 3,
  });
  upload.host.addEventListener('aui-change', () => {
    const data = new FormData();
    for (const file of upload.getFormValue()) data.append('attachments', file);
  });
}

import { FileUpload } from '@absoluteui/components/file-upload';

